      "term": "k-익명성 / l-다양성 / t-근접성 (프라이버시 모델)",
      "definition": "k-익명성: 동일 준식별자 집단(동질집합) 내 최소 k명 이상 존재해 개인 식별 방지(단점: 동질성/배경지식 공격에 취약). l-다양성: 동질집합 내 민감정보가 최소 l개 이상의 다양한 값을 가짐. t-근접성: 민감정보의 분포가 전체 데이터 분포와 t 이내로 유사하게 유지.",
      "tip": "순서: k-익명성(식별 방지) → l-다양성(민감정보 다양화) → t-근접성(분포 차이 제한)",
