      "definition": "조건절(A) → 결과절(B) 형태의 동시 구매 패턴 분석:\n1) 지지도(Support) = P(A∩B) = (A와 B 동시 포함 거래 수) / (전체 거래 수)\n2) 신뢰도(Confidence) = P(B|A) = P(A∩B) / P(A) = (A와 B 동시 거래 수) / (A 포함 거래 수)\n3) 향상도(Lift) = P(B|A) / P(B) = P(A∩B) / [P(A) × P(B)]\n- 향상도 해석: Lift = 1 (A와 B는 서로 독립), Lift > 1 (양의 상관관계, 동시 구매 시너지!), Lift < 1 (음의 상관관계).\n- Apriori 알고리즘: 최소 지지도(Minimum Support) 이상의 빈발항목집합만 확장해 계산량 축소(아이템이 너무 많으면 반복 스캔 병목 발생 → 이를 FP-Tree 구조로 해결한 것이 FP-Growth).",
      "tip": "향상도(Lift) 공식 = P(A∩B) / (P(A)×P(B))! Lift=1 이면 독립, Lift>1 이면 양의 상관관계!",
