      "definition": "서로 독립된 두 집단이 아니라, '동일한 집단의 처치 전(Before)과 후(After)'처럼 짝지어진 표본의 평균 차이를 검정하는 기법입니다.",
      "tip": "시험 선지 빈출 개념 비교",
