      "term": "상관분석",
      "definition": "두 연속형 변수 간의 선형적 관련성(상관계수 r)의 강도와 방향을 측정하는 기법이지, 3개 이상 집단의 평균 차이를 검정하는 기법(ANOVA)이 아닙니다.",
