      "definition": "데이터 범위를 0~1(Min-Max) 등으로 스케일링하는 전처리 기법이지, 오즈에 자연로그를 취하는 '로짓(Logit) 변환'이 아닙니다.",
      "tip": "시험 선지 빈출 개념 비교",
