      "definition": "CHAID 알고리즘에서 목표변수가 '연속형'일 때 ANOVA 기반으로 분할하는 기준입니다. 목표변수가 '범주형'일 때 CHAID는 '카이제곱(χ²) 통계량'을 사용합니다.",
